using System.ComponentModel;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddSingleton<Notepad>();

builder.Services.AddChatClient(cb => cb
    .UseOpenAIChatClient(
        builder.Configuration["AI:Model"] ?? "gpt-4o-mini-2024-07-18",
        builder.Configuration["AI:Endpoint"] is string endpoint ? new Uri(endpoint) : null,
        builder.Configuration["AI:ApiKey"]
            ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
            ?? throw new InvalidOperationException(
                "Set AI:ApiKey in configuration or the OPENAI_API_KEY environment variable.")));

builder.Services.AddSingleton(sp =>
{
    var chatClient = sp.GetRequiredService<IChatClient>();
    var notepad = sp.GetRequiredService<Notepad>();
    var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

    var tools = new List<AITool>
    {
        AIFunctionFactory.Create(WebSearchTool.SearchWebAsync, nameof(WebSearchTool.SearchWebAsync)),
        AIFunctionFactory.Create(notepad.AddNote, nameof(notepad.AddNote)),
        AIFunctionFactory.Create(notepad.GetNotes, nameof(notepad.GetNotes)),
    };

    return new ChatClientAgent(chatClient, new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI agent that researches topics by searching the web and taking notes.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = tools,
        },
    }, loggerFactory);
});

using var host = builder.Build();

var agent = host.Services.GetRequiredService<ChatClientAgent>();
var logger = host.Services.GetRequiredService<ILoggerFactory>().CreateLogger("ResearchAgent");
var notepad = host.Services.GetRequiredService<Notepad>();

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var instructions = $"""
    You are a research assistant. Your goal is to research the following topic thoroughly:
    "{topic}"

    Follow these steps:
    1. Search the web for information about the topic using multiple queries.
    2. Take notes on the key findings using the AddNote tool.
    3. After gathering enough information, retrieve your notes with GetNotes.
    4. Provide a comprehensive summary of your findings.

    Be thorough but concise. Use at least 2-3 different search queries to get diverse perspectives.
    """;

var session = await agent.CreateSessionAsync();

var response = await agent.RunAsync(
    instructions,
    session,
    new ChatClientAgentRunOptions(new ChatOptions { MaxOutputTokens = 4096 }));

Console.WriteLine("\n📋 Research Summary\n" + new string('─', 50));

foreach (var message in response.Messages)
{
    if (message.Role == ChatRole.Assistant && message.Text is { Length: > 0 } text)
    {
        Console.WriteLine(text);
    }
}

Console.WriteLine(new string('─', 50));
Console.WriteLine($"\n📝 Notes collected: {notepad.Count}");
foreach (var (i, note) in notepad.AllNotes.Select((n, i) => (i, n)))
{
    Console.WriteLine($"  {i + 1}. {note}");
}

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input)
        ? "Recent advances in quantum computing"
        : input;
}

