                Title = $"Overview of {query} - Wikipedia",
                Snippet = $"A comprehensive overview of {query}. This topic covers the fundamental concepts, " +
                          "recent developments, and key contributors to the field. Research in this area " +
                          "has accelerated significantly in recent years.",
                Url = $"https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}",
            },
            new()
            {
                Title = $"Latest Research on {query} - Nature",
                Snippet = $"Recent peer-reviewed studies on {query} reveal promising breakthroughs. " +
                          "Scientists have identified novel approaches that could transform our understanding " +
                          "and lead to practical applications within the next decade.",
                Url = $"https://www.nature.com/search?q={Uri.EscapeDataString(query)}",
            },
            new()
            {
                Title = $"{query}: Current Challenges and Future Directions",
                Snippet = $"Despite significant progress, {query} faces several challenges including scalability, " +
                          "cost, and reproducibility. Experts suggest that interdisciplinary collaboration " +
                          "and increased funding will be critical to overcoming these obstacles.",
                Url = $"https://arxiv.org/search/?query={Uri.EscapeDataString(query)}",
            },
            new()
            {
                Title = $"Industry Applications of {query} - TechReview",
                Snippet = $"Major technology companies are investing heavily in {query}. " +
                          "Applications range from healthcare and finance to climate science. " +
                          "Market analysts project the sector will grow substantially by 2030.",
                Url = $"https://www.technologyreview.com/search?q={Uri.EscapeDataString(query)}",
            },
            new()
            {
                Title = $"A Beginner's Guide to {query}",
                Snippet = $"New to {query}? This guide covers the basics, from foundational principles " +
                          "to cutting-edge developments. Learn about the key terminology, major milestones, " +
                          "and how this field connects to broader scientific endeavors.",
