using System.ComponentModel;

namespace ResearchAgent;

/// <summary>
/// A simple note-taking tool that the agent uses to collect research findings.
/// </summary>
internal sealed class Notepad
{
    private readonly List<string> _notes = [];

    public int Count => _notes.Count;

    public IReadOnlyList<string> AllNotes => _notes;

    [Description("Saves a research note. Use this to record key findings, facts, or insights discovered during research.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Retrieves all notes taken so far. Use this to review collected research before writing a summary.")]
    public IReadOnlyList<string> GetNotes()
    {
        return _notes;
    }
}

