+using System.ComponentModel;
+using System.Net.Http.Json;
+using System.Text.Json;
+using System.Text.Json.Serialization;
+
+namespace ResearchAgent;
+
+/// <summary>
+/// Provides web search capability using a search API or simulated results.
+/// </summary>
+internal static class WebSearchTool
+{
+    private static readonly HttpClient s_httpClient = new()
+    {
+        Timeout = TimeSpan.FromSeconds(15),
+    };
+
+    [Description("Searches the web for information on a given query and returns relevant results with titles, snippets, and URLs.")]
+    public static async Task<IReadOnlyList<SearchResult>> SearchWebAsync(
+        [Description("The search query string")] string query,
+        [Description("Maximum number of results to return (1-5)")] int maxResults = 3)
+    {
+        maxResults = Math.Clamp(maxResults, 1, 5);
+
+        // Try Brave Search API if a key is configured
+        var braveKey = Environment.GetEnvironmentVariable("BRAVE_SEARCH_API_KEY");
+        if (!string.IsNullOrEmpty(braveKey))
+        {
+            return await SearchWithBraveAsync(query, maxResults, braveKey);
+        }
+
+        // Fall back to simulated search for demo purposes
+        return SimulateSearch(query, maxResults);
+    }
+
+    private static async Task<IReadOnlyList<SearchResult>> SearchWithBraveAsync(
+        string query, int maxResults, string apiKey)
+    {
+        var encodedQuery = Uri.EscapeDataString(query);
+        var url = $"https://api.search.brave.com/res/v1/web/search?q={encodedQuery}&count={maxResults}";
+
+        using var request = new HttpRequestMessage(HttpMethod.Get, url);
+        request.Headers.Add("X-Subscription-Token", apiKey);
+        request.Headers.Add("Accept", "application/json");
+
+        using var response = await s_httpClient.SendAsync(request);
+        response.EnsureSuccessStatusCode();
+
+        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
+
+        var results = new List<SearchResult>();
+        if (json.TryGetProperty("web", out var web) &&
+            web.TryGetProperty("results", out var webResults))
+        {
+            foreach (var item in webResults.EnumerateArray().Take(maxResults))
+            {
+                results.Add(new SearchResult
+                {
+                    Title = item.GetProperty("title").GetString() ?? "",
+                    Snippet = item.GetProperty("description").GetString() ?? "",
+                    Url = item.GetProperty("url").GetString() ?? "",
+                });
+            }
+        }
+
+        return results;
+    }
+
+    private static IReadOnlyList<SearchResult> SimulateSearch(string query, int maxResults)
+    {
+        // Deterministic simulated results for demo/testing when no search API is available
+        var results = new List<SearchResult>
+        {
+            new()
+            {
+                Title = $"Overview of {query} - Wikipedia",
+                Snippet = $"A comprehensive overview of {query}. This topic covers the fundamental concepts, " +
+                          "recent developments, and key contributors to the field. Research in this area " +
+                          "has accelerated significantly in recent years.",
+                Url = $"https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}",
+            },
+            new()
+            {
+                Title = $"Latest Research on {query} - Nature",
+                Snippet = $"Recent peer-reviewed studies on {query} reveal promising breakthroughs. " +
+                          "Scientists have identified novel approaches that could transform our understanding " +
+                          "and lead to practical applications within the next decade.",
+                Url = $"https://www.nature.com/search?q={Uri.EscapeDataString(query)}",
+            },
+            new()
+            {
+                Title = $"{query}: Current Challenges and Future Directions",
+                Snippet = $"Despite significant progress, {query} faces several challenges including scalability, " +
+                          "cost, and reproducibility. Experts suggest that interdisciplinary collaboration " +
+                          "and increased funding will be critical to overcoming these obstacles.",
+                Url = $"https://arxiv.org/search/?query={Uri.EscapeDataString(query)}",
+            },
+            new()
+            {
+                Title = $"Industry Applications of {query} - TechReview",
+                Snippet = $"Major technology companies are investing heavily in {query}. " +
+                          "Applications range from healthcare and finance to climate science. " +
+                          "Market analysts project the sector will grow substantially by 2030.",
+                Url = $"https://www.technologyreview.com/search?q={Uri.EscapeDataString(query)}",
+            },
+            new()
+            {
+                Title = $"A Beginner's Guide to {query}",
+                Snippet = $"New to {query}? This guide covers the basics, from foundational principles " +
+                          "to cutting-edge developments. Learn about the key terminology, major milestones, " +
+                          "and how this field connects to broader scientific endeavors.",
+                Url = $"https://www.sciencedirect.com/search?qs={Uri.EscapeDataString(query)}",
+            },
+        };
+
+        return results.Take(maxResults).ToList();
+    }
+}
+
